import React, { useState, useEffect } from "react";

function SpeechToText() {
  const [isListening, setIsListening] = useState(false);
  const [transcript, setTranscript] = useState("");
  const [recognition, setRecognition] = useState(null);

  useEffect(() => {
    const SpeechRecognition =
      window.SpeechRecognition || window.webkitSpeechRecognition;

    if (!SpeechRecognition) {
      alert("Your browser does not support speech recognition.");
      return;
    }

    const recognizer = new SpeechRecognition();
    recognizer.lang = "en-US";
    recognizer.interimResults = false;
    recognizer.continuous = false;

    recognizer.onresult = (event) => {
      const speech = event.results[0][0].transcript;
      setTranscript(speech);
      setIsListening(false);
    };

    recognizer.onerror = (event) => {
      console.error("Speech recognition error:", event.error);

      if (event.error === "network") {
        alert(
          "⚠️ Could not connect to Google's speech recognition service.\nCheck internet, VPN, firewall, or browser settings."
        );
      }

      setIsListening(false);
    };

    recognizer.onstart = () => {
      console.log("🎤 Microphone is listening...");
    };

    recognizer.onaudioend = () => {
      console.log("🛑 Microphone stopped.");
    };

    setRecognition(recognizer);
  }, []);

  const handleStart = () => {
    if (recognition && !isListening) {
      setTranscript("");
      setIsListening(true);
      try {
        recognition.start();
      } catch (err) {
        console.error("SpeechRecognition start error:", err);
      }
    }
  };

  const handleStop = () => {
    if (recognition && isListening) {
      recognition.stop();
      setIsListening(false);
    }
  };

  return (
    <div style={{ padding: "20px", textAlign: "center" }}>
      <h2>🎙️ Talk to SACA</h2>
      <button onClick={handleStart} disabled={isListening}>
        Start Talking
      </button>
      <button
        onClick={handleStop}
        disabled={!isListening}
        style={{ marginLeft: "10px" }}
      >
        Stop
      </button>

      <div style={{ marginTop: "20px" }}>
        <p>
          <strong>📝 You said:</strong>
        </p>
        <div
          style={{
            padding: "10px",
            border: "1px solid #ccc",
            minHeight: "40px",
          }}
        >
          {transcript || "(waiting for input...)"}
        </div>
      </div>
    </div>
  );
}

export default SpeechToText;
